Ок, на Go:

1. **Лови сигнал через `signal.NotifyContext`** — не руками `os.Signal`, получишь готовый ctx для отмены.
2. **`Shutdown(ctx)` вместо `Close()`** — перестаёт принимать новые соединения и ждёт активные запросы.
3. **Дай дедлайн через `context.WithTimeout`** — иначе висеть будешь вечно, если хендлер завис.
4. **Отдельный ctx для `ListenAndServe`**, чтобы отличить штатное `ErrServerClosed` от реальной ошибки.
5. **Закрывай ресурсы после** — БД, пулы, флаш трейсов: сначала сервер, потом зависимости.

```go
func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	srv := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
	}

	errCh := make(chan error, 1)
	go func() {
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			errCh <- err
		}
	}()

	select {
	case err := <-errCh:
		log.Fatalf("listen: %v", err)
	case <-ctx.Done():
		log.Println("shutting down")
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	if err := srv.Shutdown(shutdownCtx); err != nil {
		log.Printf("forced shutdown: %v", err)
		_ = srv.Close()
	}

	// db.Close(), tracerProvider.Shutdown() и т.п.
}
```

Нюанс: `Shutdown` **не** убивает зависшие хендлеры по таймауту — если дедлайн истёк, нужен `srv.Close()`. И не забудь про `BaseContext` в `http.Server`, если хочешь общий контекст для всех запросов.

`Shutdown` даёт дожить активным запросам, но не убивает зависшие по таймауту — на этот случай `Close()`. Ресурсы закрывай после сервера.

```go
func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	srv := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
	}

	errCh := make(chan error, 1)
	go func() {
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			errCh <- err
		}
	}()

	select {
	case err := <-errCh:
		log.Fatalf("listen: %v", err)
	case <-ctx.Done():
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	if err := srv.Shutdown(shutdownCtx); err != nil {
		_ = srv.Close()
	}

	// db.Close(), tracerProvider.Shutdown()
}
```

