Причина — отсутствие дедлайна на запросе. Задайте `context.WithTimeout` и явный `Timeout` у `http.Client`, иначе зависание клиента не ограничено.

```go
var payClient = &http.Client{
	Timeout: 10 * time.Second,
	Transport: &http.Transport{
		DialContext:         (&net.Dialer{Timeout: 3 * time.Second}).DialContext,
		TLSHandshakeTimeout: 3 * time.Second,
		ResponseHeaderTimeout: 5 * time.Second,
		MaxIdleConnsPerHost: 20,
	},
}

func (s *Service) Pay(ctx context.Context, req PaymentReq) (*PaymentResp, error) {
	ctx, cancel := context.WithTimeout(ctx, 8*time.Second)
	defer cancel()

	body, err := json.Marshal(req)
	if err != nil {
		return nil, fmt.Errorf("marshal: %w", err)
	}

	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, s.payURL+"/payments", bytes.NewReader(body))
	if err != nil {
		return nil, fmt.Errorf("new request: %w", err)
	}
	httpReq.Header.Set("Content-Type", "application/json")

	resp, err := payClient.Do(httpReq)
	if err != nil {
		return nil, fmt.Errorf("pay api: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode >= 500 || resp.StatusCode == http.StatusTooManyRequests {
		return nil, ErrPayUnavailable
	}
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("pay api: status %d", resp.StatusCode)
	}

	var out PaymentResp
	if err := json.NewDecoder(io.LimitReader(resp.Body, 1<<20)).Decode(&out); err != nil {
		return nil, fmt.Errorf("decode: %w", err)
	}
	return &out, nil
}
```

Повторы делайте только для идемпотентных запросов и с `Idempotency-Key`; таймаут передавайте вниз по цепочке через `ctx`, а не дублируйте в слоях.

Причина — отсутствие дедлайна: задайте таймаут на `http.Client` и передавайте `context.WithTimeout` в запрос, чтобы горутина не висела бесконечно.

```go
var payClient = &http.Client{
	Timeout: 5 * time.Second,
	Transport: &http.Transport{
		DialContext:         (&net.Dialer{Timeout: 2 * time.Second}).DialContext,
		ResponseHeaderTimeout: 3 * time.Second,
		MaxIdleConnsPerHost:   20,
	},
}

func (s *PayService) Charge(ctx context.Context, req ChargeRequest) (*ChargeResponse, error) {
	ctx, cancel := context.WithTimeout(ctx, 7*time.Second)
	defer cancel()

	body, err := json.Marshal(req)
	if err != nil {
		return nil, fmt.Errorf("marshal: %w", err)
	}

	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost,
		s.baseURL+"/charge", bytes.NewReader(body))
	if err != nil {
		return nil, fmt.Errorf("new request: %w", err)
	}
	httpReq.Header.Set("Content-Type", "application/json")

	resp, err := payClient.Do(httpReq)
	if err != nil {
		if errors.Is(err, context.DeadlineExceeded) {
			return nil, ErrPayTimeout
		}
		return nil, fmt.Errorf("do: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("pay: status %d", resp.StatusCode)
	}

	var out ChargeResponse
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return nil, fmt.Errorf("decode: %w", err)
	}
	return &out, nil
}
```

Вызов — с ограничением сверху: `errgroup`/семафор, чтобы зависший внешний сервис не исчерпал весь пул горутин. Для устойчивости добавьте circuit breaker (например, `gobreaker`) и retry с backoff только на идемпотентные запросы с `Idempotency-Key`.

Причина — отсутствие дедлайна: `http.Client` без `Timeout` и контекст без дедлайна ждут ответа бесконечно. Ограничьте время на уровне клиента и передавайте дедлайн из входящего запроса.

```go
// общий клиент: страховка на уровне транспорта
var payClient = &http.Client{
	Timeout: 5 * time.Second,
	Transport: &http.Transport{
		DialContext:         (&net.Dialer{Timeout: 2 * time.Second}).DialContext,
		TLSHandshakeTimeout: 2 * time.Second,
		ResponseHeaderTimeout: 3 * time.Second,
		MaxIdleConnsPerHost: 32,
	},
}

var errPayTimeout = errors.New("payment api timeout")

func (c *PayClient) Charge(ctx context.Context, req ChargeRequest) (*ChargeResponse, error) {
	// дедлайн операции, не длиннее дедлайна вызывающего
	ctx, cancel := context.WithTimeout(ctx, 4*time.Second)
	defer cancel()

	body, err := json.Marshal(req)
	if err != nil {
		return nil, fmt.Errorf("marshal: %w", err)
	}

	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, c.baseURL+"/charge", bytes.NewReader(body))
	if err != nil {
		return nil, fmt.Errorf("new request: %w", err)
	}
	httpReq.Header.Set("Content-Type", "application/json")

	resp, err := c.client.Do(httpReq)
	if err != nil {
		if errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled) {
			return nil, fmt.Errorf("%w: %v", errPayTimeout, err)
		}
		return nil, fmt.Errorf("do: %w", err)
	}
	defer func() {
		io.Copy(io.Discard, io.LimitReader(resp.Body, 1<<16))
		resp.Body.Close()
	}()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("payment api status %d", resp.StatusCode)
	}

	// читаем тело тоже под дедлайном
	var out ChargeResponse
	if err := json.NewDecoder(io.LimitReader(resp.Body, 1<<20)).Decode(&out); err != nil {
		return nil, fmt.Errorf("decode: %w", err)
	}
	return &out, nil
}
```

